using System;
using System.IO;
using System.Linq;
using System.Collections;
using System.Collections.Generic;
using UnityEngine;
using HarborValeGreybox.Launch;
using HarborValeGreybox.Racing;
namespace HarborValeGreybox.Workshop {
public sealed class TabsTirePlayerProbe:MonoBehaviour {
 static string folder;List<string> checks=new List<string>();bool failed;double deadline;
 [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.BeforeSceneLoad)]static void Prepare(){var args=Environment.GetCommandLineArgs();int i=Array.IndexOf(args,"--tabs-tire-check-dir");folder=Debug.isDebugBuild&&i>=0&&i+1<args.Length?Path.GetFullPath(args[i+1]):null;if(folder!=null){Directory.CreateDirectory(folder);DocksideTrialDirector.SavePathOverrideForTests=Path.Combine(folder,"isolated-v5.json");}}
 [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.AfterSceneLoad)]static void Hook(){if(folder==null)return;var g=new GameObject("Tabbed garage and rubber audio verification");DontDestroyOnLoad(g);g.AddComponent<TabsTirePlayerProbe>();}
 void Check(bool yes,string text){checks.Add((yes?"PASS ":"FAIL ")+text);Write();if(!yes){failed=true;Application.Quit(1);throw new Exception(text);}}
 void Write()=>File.WriteAllLines(Path.Combine(folder,"results.txt"),checks);
 void OnEnable(){Application.logMessageReceived+=Log;}void OnDisable(){Application.logMessageReceived-=Log;}void Log(string text,string stack,LogType kind){if(!failed&&(kind==LogType.Exception||kind==LogType.Error)){failed=true;checks.Add("FAIL runtime "+text);Write();Application.Quit(1);}}
 void Update(){if(!failed&&deadline>0&&Time.realtimeSinceStartupAsDouble>deadline)Check(false,"Tabs/audio native timeout");}
 IEnumerator Wait(Func<bool> ready){while(!ready())yield return null;yield return new WaitForSecondsRealtime(.3f);}
 IEnumerator Capture(string file){yield return new WaitForEndOfFrame();ScreenCapture.CaptureScreenshot(Path.Combine(folder,file+".png"));yield return new WaitForSecondsRealtime(.35f);Check(new FileInfo(Path.Combine(folder,file+".png")).Length>50000,"Rendered garage screenshot is nonblank: "+file);}
 static TrialSession Finish(TrialDefinition d){var s=new TrialSession(d);s.Tick(4,Vector3.zero,Vector3.zero);s.Tick(90,Vector3.zero,Vector3.zero);foreach(var g in d.checkpoints)s.Tick(.02f,g.Position-g.Forward,g.Position+g.Forward);return s;}
 IEnumerator Start(){deadline=Time.realtimeSinceStartupAsDouble+150;yield return Wait(()=>HarborValeLaunch.Instance!=null);HarborValeLaunch.Instance.Open(HarborValeLaunch.CityScene);yield return Wait(()=>FindAnyObjectByType<ExpandedWorkshop>()?.Ready==true);var shop=FindAnyObjectByType<ExpandedWorkshop>();var trial=FindAnyObjectByType<DocksideTrialDirector>();for(int i=0;i<70;i++)trial.Store.Settle(Finish(trial.Definition),out _);Check(shop.Open(),"Paid Finch opens new tabbed garage");Check(shop.View.ActiveTab=="na","First garage opens on Engine tunes");
  foreach(var tab in WorkshopTabs.All){shop.View.SelectTab(tab.id);var visible=shop.View.Visible();Check(visible.Count>0&&visible.All(o=>WorkshopTabs.Contains(tab.id,o))&&visible.Any(o=>o.id==shop.SelectedId),"Finch tab selects only visible parts: "+tab.label);}
  shop.View.SelectTab("roots");Check(shop.View.Visible().Count==3,"Supercharger tab contains its three stages only");Screen.SetResolution(1400,800,FullScreenMode.Windowed);yield return new WaitForSecondsRealtime(.4f);Screen.SetResolution(1280,720,FullScreenMode.Windowed);yield return new WaitForSecondsRealtime(.6f);yield return Capture("Finch_Supercharger_1280x720");Check(shop.GuideToRequirement()&&shop.SelectedId=="na_1"&&shop.View.ActiveTab=="na","Missing requirement action jumps to Engine tunes tab");Check(shop.InstallVisibleSelection(),"Visible required engine stage purchases through real store");shop.View.Reveal("induction_roots_1");Check(shop.GuideToRequirement()&&shop.View.ActiveTab=="gearbox","Next missing requirement jumps to Gearbox tab");Check(shop.InstallVisibleSelection(),"Visible gearbox stage purchases through real store");shop.View.SelectTab("roots");Check(shop.InstallVisibleSelection(),"Supercharger stage purchases from its own tab");int balance=shop.Credits;Check(!shop.InstallVisibleSelection()&&shop.Credits==balance,"Repeated installed selection cannot charge twice");
  shop.View.SelectTab("twin");Check(shop.View.Visible().Count==3&&shop.View.Visible().All(o=>shop.Requirement(o)!=null),"Finch twin-turbo tab clearly retains Apex-only restrictions");Check(!shop.InstallVisibleSelection()&&shop.Credits==balance,"Finch cannot buy incompatible twin turbo from tab");shop.View.Search="no matching item";Check(shop.View.Visible().Count==0&&!shop.InstallVisibleSelection()&&shop.Credits==balance,"Empty tab search cannot purchase hidden prior selection");shop.View.SelectTab("brakes");Check(shop.View.Search==""&&shop.View.Visible().Count==3,"Changing tabs clears search and reveals all brake stages");
  foreach(var o in shop.Catalog.MissingPath(shop.Build,shop.Catalog.Find("induction_roots_3")))Check(shop.Install(o.id),"Paid burnout fixture stage "+o.id);shop.View.Reveal("induction_roots_3");Screen.SetResolution(1600,900,FullScreenMode.Windowed);yield return new WaitForSecondsRealtime(.5f);yield return Capture("Finch_Supercharger_1600x900");shop.Close();var car=shop.Car;car.externalInput=true;car.commandedHandbrake=false;car.commandedSteer=0;car.commandedPedal=1;car.commandedServiceBrake=1;var tap=Camera.main.gameObject.AddComponent<TurboNativeAudioTap>();tap.Begin();yield return new WaitForSecondsRealtime(2.5f);car.commandedServiceBrake=0;float peak=0,speed=0;double until=Time.realtimeSinceStartupAsDouble+4;while(Time.realtimeSinceStartupAsDouble<until){peak=Mathf.Max(peak,car.GetComponent<WorkshopEffects>().SquealGain);speed=Mathf.Max(speed,car.GetComponentInChildren<WorkshopAudioVoice>().tireSpeed);yield return null;}checks.Add("MEASURE actual tire gain="+peak+" speed="+speed);Check(peak>.01f&&speed>5,"Actual driven-wheel slip and road speed reach new tire audio layer");Check(tap.Finish(Path.Combine(folder,"Finch_Actual_Tire_Mix.wav"))>10000,"Native audio listener records loaded tire/engine mix");Destroy(tap);car.commandedPedal=0;car.Recover();yield return new WaitForSecondsRealtime(.8f);Check(car.GetComponent<WorkshopEffects>().SquealGain==0,"Recovered stationary car stops requesting squeal");car.externalInput=false;string paid=File.ReadAllText(trial.Store.PathName);
  HarborValeLaunch.Instance.Open(HarborValeLaunch.MenuScene);yield return Wait(()=>!HarborValeLaunch.Instance.Busy);HarborValeLaunch.Instance.Open(HarborValeLaunch.SportsScene);yield return Wait(()=>FindAnyObjectByType<ExpandedWorkshop>()?.Ready==true);shop=FindAnyObjectByType<ExpandedWorkshop>();Check(shop.Open(),"Free Apex opens same tabbed interface");shop.View.SelectTab("twin");Check(shop.View.Visible().Select(o=>o.stage).SequenceEqual(new[]{1,2,3}),"Apex twin-turbo stages appear in order under Twin turbo");foreach(var o in shop.Catalog.MissingPath(shop.Build,shop.Catalog.Find("induction_twin_3")))Check(shop.Install(o.id),"Free Apex twin path "+o.id);shop.View.Reveal("induction_twin_3");yield return Capture("Apex_TwinTurbo_1600x900");Check(shop.Build.induction=="twin"&&shop.Build.inductionStage==3,"Twin turbo tab installs actual Apex hardware/curve");shop.View.SelectTab("sound");yield return Capture("Apex_SoundTunes_1600x900");Check(File.ReadAllText(DocksideTrialDirector.SavePathOverrideForTests)==paid,"Free Apex tab installs leave paid Finch ledger byte-identical");Check(shop.Car.GetComponentsInChildren<WheelCollider>().Length==4&&shop.Car.GetComponentsInChildren<AudioSource>().Length==1,"Tabs and tire audio add no duplicate physics or engine sources");Check(!failed,"No native tab/audio runtime errors");Write();Application.Quit(0);
 }
}
}
